import GoogleMaps from '@/components/GoogleMaps.vue';
export default {
  props: {
    viewSwipeLocation: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      center: {
        lat: 45.508,
        lng: -73.587
      },
      markers: [],
      googleMarkers: [],
      places: [],
      currentPlace: null,
      newitem: [],
      headers: [{
        title: "Swiped Source",
        key: "swipe_source",
        sortable: false
      }, {
        title: "Swiped Location",
        key: "location_id",
        sortable: false
      }, {
        title: "Swiped Time",
        key: "swiped_time",
        sortable: false
      }],
      tableLoading: false,
      fixed: true,
      height: 0
    };
  },
  watch: {
    viewSwipeLocation: {
      async handler() {
        if (this.viewSwipeLocation == true) {
          this.height = window.innerHeight - 340;
          this.newitem = this.rowInfo.swipe_list;
          this.markers = [];
          let baseImage = "https://maps.google.com/mapfiles/ms/icons/";
          let markerImage = ["red-dot.png", "yellow-dot.png", "green-dot.png", "blue-dot.png", "orange-dot.png", "purple-dot.png", "pink-dot.png"];
          for (let i = 0; i < this.newitem.length; i++) {
            this.markers.push({
              position: {
                lat: Number(this.newitem[i].swipe_lat),
                lng: Number(this.newitem[i].swipe_long)
              },
              marker: baseImage + markerImage[Math.floor(Math.random() * markerImage.length)],
              title: this.newitem[i].location_id || `Marker ${i + 1}`
            });
          }
          // Map to GoogleMaps.vue expected format
          this.googleMarkers = this.markers.map(m => ({
            position: m.position,
            title: m.title
          }));
        }
      },
      immediate: true
    }
  },
  methods: {
    get_date(date) {
      let a = new Date(date).toLocaleTimeString("en-In", {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit"
      });
      return a.toUpperCase();
    },
    close_dialog() {
      this.$emit("clicked", 0);
    }
  },
  components: {
    GoogleMaps
  }
};
